  clearAngularVelocity: boolean;
}

export interface ObstacleEffect {
  obstacleId: string;
  kind: ForceObstacleKind;
  deltaVelocity?: Vec3;
  teleport?: TeleportEffect;
}

export interface ObstacleConfigBase {
  id: string;
  kind: ForceObstacleKind;
  enabled?: boolean;
}

export interface ObstacleStepContext {
  dt: number;
  elapsed: number;
}

export interface BallObstacle<TConfig extends ObstacleConfigBase = ObstacleConfigBase> {
  readonly id: string;
  readonly kind: ForceObstacleKind;
  readonly config: TConfig;
  enabled: boolean;
  update(ball: BallSample, context: ObstacleStepContext): ObstacleEffect | null;
  reset(): void;
}

export interface TeleporterConfig extends ObstacleConfigBase {
  kind: 'teleporter';
  entryZone: ZoneShape;
  exitPosition: Vec3;
  exitVelocityScale?: number;
  clearAngularVelocity?: boolean;
}

export interface FanConfig extends ObstacleConfigBase {
  kind: 'fan';
  zone: ZoneShape;
  direction: Vec3;
  maxForce: number;
  falloff?: boolean;
  pulse?: { period: number; minMultiplier: number };
}

export interface ConveyorConfig extends ObstacleConfigBase {
  kind: 'conveyor';
  zone: ZoneShape;
  direction: Vec3;
  targetSpeed: number;
  coupling?: number;
