import type { BallObstacle, BallSample, ObstacleEffect, ObstacleStepContext, TeleporterConfig } from './types';
import { zoneContains } from './zones';
import { scaleVec3 } from './vec';

export class TeleporterObstacle implements BallObstacle<TeleporterConfig> {
  public readonly id: string;
  public readonly kind = 'teleporter' as const;
  public readonly config: TeleporterConfig;
  public enabled: boolean;
  private hasTeleported = false;

  constructor(config: TeleporterConfig) {
    this.id = config.id;
    this.config = config;
    this.enabled = config.enabled ?? true;
  }

  update(ball: BallSample, _context: ObstacleStepContext): ObstacleEffect | null {
    if (!this.enabled || this.hasTeleported) return null;
    if (zoneContains(this.config.entryZone, ball.position, ball.radius ?? 0.1)) {
      this.hasTeleported = true;
      const exitVel = this.config.exitVelocityScale !== undefined
        ? scaleVec3(ball.velocity, this.config.exitVelocityScale)
        : ball.velocity;

      return {
        obstacleId: this.id,
        kind: this.kind,
        teleport: {
          position: this.config.exitPosition,
          velocity: exitVel,
          clearAngularVelocity: this.config.clearAngularVelocity ?? true,
        },
      };
    }
    return null;
  }

  reset(): void {
    this.hasTeleported = false;
  }
}
