import type { BallObstacle, BallSample, FanConfig, ObstacleEffect, ObstacleStepContext } from './types';
import { zoneContains, zoneFalloff } from './zones';
import { scaleVec3 } from './vec';

export class FanObstacle implements BallObstacle<FanConfig> {
  public readonly id: string;
  public readonly kind = 'fan' as const;
  public readonly config: FanConfig;
  public enabled: boolean;

  constructor(config: FanConfig) {
    this.id = config.id;
    this.config = config;
    this.enabled = config.enabled ?? true;
  }

  update(ball: BallSample, context: ObstacleStepContext): ObstacleEffect | null {
    if (!this.enabled) return null;
    if (!zoneContains(this.config.zone, ball.position, ball.radius ?? 0.1)) return null;

    const falloff = this.config.falloff !== false ? zoneFalloff(this.config.zone, ball.position) : 1;
    if (falloff <= 0) return null;

    let multiplier = 1;
    if (this.config.pulse) {
      const { period, minMultiplier } = this.config.pulse;
      if (period > 0) {
        const t = (context.elapsed % period) / period;
        multiplier = minMultiplier + (1 - minMultiplier) * (0.5 + 0.5 * Math.sin(t * Math.PI * 2));
      }
    }

    const force = this.config.maxForce * falloff * multiplier * context.dt;
    const deltaV = scaleVec3(this.config.direction, force);

    return {
      obstacleId: this.id,
      kind: this.kind,
      deltaVelocity: deltaV,
    };
  }

  reset(): void {}
}
