import type { BallObstacle, BallSample, ConveyorConfig, ObstacleEffect, ObstacleStepContext } from './types';
import { zoneContains } from './zones';
import { scaleVec3, subVec3 } from './vec';
import { clamp } from '../physics/helpers';

export class ConveyorObstacle implements BallObstacle<ConveyorConfig> {
  public readonly id: string;
  public readonly kind = 'conveyor' as const;
  public readonly config: ConveyorConfig;
  public enabled: boolean;

  constructor(config: ConveyorConfig) {
    this.id = config.id;
    this.config = config;
    this.enabled = config.enabled ?? true;
  }

  update(ball: BallSample, context: ObstacleStepContext): ObstacleEffect | null {
    if (!this.enabled) return null;
    if (!zoneContains(this.config.zone, ball.position, ball.radius ?? 0.1)) return null;

    const targetVel = scaleVec3(this.config.direction, this.config.targetSpeed);
    const currentVel = ball.velocity;
    const coupling = this.config.coupling ?? 5.0;
    const deltaV = scaleVec3(subVec3(targetVel, currentVel), clamp(coupling * context.dt, 0, 1));

    return {
      obstacleId: this.id,
      kind: this.kind,
      deltaVelocity: deltaV,
    };
  }

  reset(): void {}
}
