import { describe, it, expect } from 'vitest';
import { TeleporterObstacle } from './teleporter';
import type { TeleporterConfig } from './types';
import { vec3 } from './vec';

describe('TeleporterObstacle', () => {
  const config: TeleporterConfig = {
    id: 'tp1',
    kind: 'teleporter',
    entryZone: { shape: 'sphere', center: vec3(0, 0, 0), radius: 1 },
    exitPosition: vec3(10, 0, 10),
    exitVelocityScale: 0.5,
    clearAngularVelocity: true,
  };

  it('should teleport the ball when inside entry zone', () => {
    const obstacle = new TeleporterObstacle(config);
    const ball = { position: vec3(0, 0, 0), velocity: vec3(1, 0, 1) };
    const effect = obstacle.update(ball, { dt: 0.016, elapsed: 0 });

    expect(effect).not.toBeNull();
    expect(effect?.teleport?.position).toEqual(vec3(10, 0, 10));
    expect(effect?.teleport?.velocity).toEqual(vec3(0.5, 0, 0.5));
    expect(effect?.teleport?.clearAngularVelocity).toBe(true);
  });

  it('should not teleport if already teleported this hole', () => {
    const obstacle = new TeleporterObstacle(config);
    const ball = { position: vec3(0, 0, 0), velocity: vec3(1, 0, 1) };
    obstacle.update(ball, { dt: 0.016, elapsed: 0 });
    const effect2 = obstacle.update(ball, { dt: 0.016, elapsed: 0.016 });
    expect(effect2).toBeNull();
  });

  it('should reset teleport state', () => {
    const obstacle = new TeleporterObstacle(config);
    const ball = { position: vec3(0, 0, 0), velocity: vec3(1, 0, 1) };
    obstacle.update(ball, { dt: 0.016, elapsed: 0 });
    obstacle.reset();
    const effect3 = obstacle.update(ball, { dt: 0.016, elapsed: 0.032 });
    expect(effect3).not.toBeNull();
  });

  it('should do nothing if disabled', () => {
    const obstacle = new TeleporterObstacle({ ...config, enabled: false });
    const ball = { position: vec3(0, 0, 0), velocity: vec3(1, 0, 1) };
    const effect = obstacle.update(ball, { dt: 0.016, elapsed: 0 });
    expect(effect).toBeNull();
  });
});
