import { describe, it, expect } from 'vitest';
import { FanObstacle } from './fan';
import type { FanConfig } from './types';
import { vec3 } from './vec';

describe('FanObstacle', () => {
  const config: FanConfig = {
    id: 'fan1',
    kind: 'fan',
    zone: { shape: 'box', center: vec3(0, 0, 0), halfExtents: vec3(2, 2, 2) },
    direction: vec3(0, 1, 0),
    maxForce: 10,
  };

  it('should apply force when ball is inside zone', () => {
    const obstacle = new FanObstacle(config);
    const ball = { position: vec3(0, 0, 0), velocity: vec3(0, 0, 0) };
    const effect = obstacle.update(ball, { dt: 0.1, elapsed: 0 });
    expect(effect).not.toBeNull();
    expect(effect?.deltaVelocity).toEqual(vec3(0, 1, 0));
  });

  it('should apply reduced force near edge of zone (falloff)', () => {
    const obstacle = new FanObstacle(config);
    const ball = { position: vec3(1.5, 0, 0), velocity: vec3(0, 0, 0) };
    const effect = obstacle.update(ball, { dt: 0.1, elapsed: 0 });
    expect(effect).not.toBeNull();
    expect(effect?.deltaVelocity).toEqual(vec3(0, 0.25, 0));
  });

  it('should do nothing if ball is outside zone', () => {
    const obstacle = new FanObstacle(config);
    const ball = { position: vec3(3, 0, 0), velocity: vec3(0, 0, 0) };
    const effect = obstacle.update(ball, { dt: 0.1, elapsed: 0 });
    expect(effect).toBeNull();
  });

  it('should pulse force over time', () => {
    const pulseConfig: FanConfig = { ...config, pulse: { period: 2, minMultiplier: 0.5 } };
    const obstacle = new FanObstacle(pulseConfig);
    const ball = { position: vec3(0, 0, 0), velocity: vec3(0, 0, 0) };
    const effect1 = obstacle.update(ball, { dt: 0.1, elapsed: 0.5 });
    expect(effect1?.deltaVelocity?.y).toBeCloseTo(1.0, 5);
    const effect2 = obstacle.update(ball, { dt: 0.1, elapsed: 1.0 });
    expect(effect2?.deltaVelocity?.y).toBeCloseTo(0.75, 5);
  });
});
